B.aca=new A.h(B.e,["Nothing. Delivery is free on every order, anywhere in Egypt, with no minimum.","\u0628\u0628\u0644\u0627\u0634. \u0627\u0644\u062a\u0648\u0635\u064a\u0644 \u0645\u062c\u0627\u0646\u064a \u0639\u0644\u0649 \u0643\u0644 \u0627\u0644\u0637\u0644\u0628\u0627\u062a\u060c \u0644\u0623\u064a \u0645\u0643\u0627\u0646 \u0641\u064a \u0645\u0635\u0631\u060c \u0648\u0628\u062f\u0648\u0646 \u062d\u062f \u0623\u062f\u0646\u0649."],t.w)
